import{_ as t,o as s,c as i,aj as a}from"./chunks/framework.C6uXqnaX.js";const g=JSON.parse('{"title":"Testing Utility APIs","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/testing/utility-apis.md","filePath":"en/guide/testing/utility-apis.md"}'),n={name:"en/guide/testing/utility-apis.md"};function o(d,e,l,r,c,h){return s(),i("div",null,e[0]||(e[0]=[a(`<h1 id="testing-utility-apis" tabindex="-1">Testing Utility APIs <a class="header-anchor" href="#testing-utility-apis" aria-label="Permalink to &quot;Testing Utility APIs&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">NOTE</p><p>While this guide is being updated for Vitest, some descriptions and examples of utility APIs are currently presented within the context of Karma/Jasmine. We are actively working to provide Vitest equivalents and updated guidance where applicable.</p></div><p>This page describes the most useful Angular testing features.</p><p>The Angular testing utilities include the <code>TestBed</code>, the <code>ComponentFixture</code>, and a handful of functions that control the test environment. The <a href="#testbed-class-summary"><code>TestBed</code></a> and <a href="#the-componentfixture"><code>ComponentFixture</code></a> classes are covered separately.</p><p>Here&#39;s a summary of the stand-alone functions, in order of likely utility:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Function</th><th style="text-align:left;">Details</th></tr></thead><tbody><tr><td style="text-align:left;">[<code>inject</code>]</td><td style="text-align:left;">Injects one or more services from the current <code>TestBed</code> injector into a test function. It cannot inject a service provided by the component itself. See discussion of the <a href="/en/guide/testing/components-scenarios#get-injected-services">debugElement.injector</a>.</td></tr><tr><td style="text-align:left;"><code>getTestBed</code></td><td style="text-align:left;">Gets the current instance of the <code>TestBed</code>. Usually unnecessary because the static class methods of the <code>TestBed</code> class are typically sufficient. The <code>TestBed</code> instance exposes a few rarely used members that are not available as static methods.</td></tr></tbody></table><p>For handling complex asynchronous scenarios or testing legacy Zone.js-based applications, see the <a href="/en/guide/testing/zone-js-testing-utilities">Zone.js Testing Utilities</a> guide.</p><h2 id="testbed-class-summary" tabindex="-1"><code>TestBed</code> class summary <a class="header-anchor" href="#testbed-class-summary" aria-label="Permalink to &quot;\`TestBed\` class summary&quot;">​</a></h2><p>The <code>TestBed</code> class is one of the principal Angular testing utilities. Its API is quite large and can be overwhelming until you&#39;ve explored it, a little at a time. Read the early part of this guide first to get the basics before trying to absorb the full API.</p><p>The module definition passed to <code>configureTestingModule</code> is a subset of the <code>@NgModule</code> metadata properties.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> TestModuleMetadata</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  providers</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> any</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[];</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  declarations</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> any</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[];</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  imports</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> any</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[];</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  schemas</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Array</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SchemaMetadata</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> any</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[]&gt;;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre></div><p>Each override method takes a <code>MetadataOverride&lt;T&gt;</code> where <code>T</code> is the kind of metadata appropriate to the method, that is, the parameter of an <code>@NgModule</code>, <code>@Component</code>, <code>@Directive</code>, or <code>@Pipe</code>.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> MetadataOverride</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">T</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  add</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Partial</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">T</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  remove</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Partial</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">T</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  set</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Partial</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">T</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre></div><p>The <code>TestBed</code> API consists of static class methods that either update or reference a <em>global</em> instance of the <code>TestBed</code>.</p><p>Internally, all static methods cover methods of the current runtime <code>TestBed</code> instance, which is also returned by the <code>getTestBed()</code> function.</p><p>Call <code>TestBed</code> methods <em>within</em> a <code>beforeEach()</code> to ensure a fresh start before each individual test.</p><p>Here are the most important static methods, in order of likely utility.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Methods</th><th style="text-align:left;">Details</th></tr></thead><tbody><tr><td style="text-align:left;"><code>configureTestingModule</code></td><td style="text-align:left;">The testing shims establish the <a href="/en/guide/testing">initial test environment</a> and a default testing module. The default testing module is configured with basic declaratives and some Angular service substitutes that every tester needs. <br> Call <code>configureTestingModule</code> to refine the testing module configuration for a particular set of tests by adding and removing imports, declarations (of components, directives, and pipes), and providers.</td></tr><tr><td style="text-align:left;"><code>compileComponents</code></td><td style="text-align:left;">Compile the testing module asynchronously after you&#39;ve finished configuring it. You <strong>must</strong> call this method if <em>any</em> of the testing module components have asynchronously loaded resources (like @defer blocks).</td></tr><tr><td style="text-align:left;"><code>createComponent&lt;T&gt;</code></td><td style="text-align:left;">Create an instance of a component of type <code>T</code> based on the current <code>TestBed</code> configuration. After calling <code>createComponent</code>, the <code>TestBed</code> configuration is frozen for the duration of the current spec.</td></tr><tr><td style="text-align:left;"><code>overrideComponent</code></td><td style="text-align:left;">Replace metadata for the given component class, which could be nested deeply within an inner module.</td></tr><tr><td style="text-align:left;"><code>overrideDirective</code></td><td style="text-align:left;">Replace metadata for the given directive class, which could be nested deeply within an inner module.</td></tr><tr><td style="text-align:left;"><code>overridePipe</code></td><td style="text-align:left;">Replace metadata for the given pipe class, which could be nested deeply within an inner module.</td></tr><tr><td style="text-align:left;"><code>overrideModule</code></td><td style="text-align:left;">Replace metadata for the given <code>NgModule</code>. Recall that modules can import other modules. The <code>overrideModule</code> method can reach deeply into the current testing module to modify one of these inner modules.</td></tr><tr><td style="text-align:left;"><code>inject</code></td><td style="text-align:left;">Retrieve a service from the current <code>TestBed</code> injector. The <code>inject</code> function is often adequate for this purpose. But <code>inject</code> throws an error if it can&#39;t provide the service. <br> What if the service is optional? <br> The <code>TestBed.inject()</code> method takes an optional second parameter, the object to return if Angular can&#39;t find the provider (<code>null</code> in this example): <code>expect(TestBed.inject(NotProvided, null)).toBeNull();</code> After calling <code>TestBed.inject</code>, the <code>TestBed</code> configuration is frozen for the duration of the current spec.</td></tr><tr><td style="text-align:left;"><code>initTestEnvironment</code></td><td style="text-align:left;">Initialize the testing environment for the entire test run. <br> The testing shims call it for you so there is rarely a reason for you to call it yourself. <br> Call this method <em>exactly once</em>. To change this default in the middle of a test run, call <code>resetTestEnvironment</code> first. <br> Specify a default Angular testing module and a <code>PlatformRef</code>. Alternatives for non-browser platforms are available in the general form <code>@angular/platform-&lt;platform_name&gt;/testing</code>.</td></tr><tr><td style="text-align:left;"><code>resetTestEnvironment</code></td><td style="text-align:left;">Reset the initial test environment, including the default testing module.</td></tr></tbody></table><p>A few of the <code>TestBed</code> instance methods are not covered by static <code>TestBed</code> <em>class</em> methods. These are rarely needed.</p><h2 id="the-componentfixture" tabindex="-1">The <code>ComponentFixture</code> <a class="header-anchor" href="#the-componentfixture" aria-label="Permalink to &quot;The \`ComponentFixture\`&quot;">​</a></h2><p>The <code>TestBed.createComponent&lt;T&gt;</code> creates an instance of the component <code>T</code> and returns a strongly typed <code>ComponentFixture</code> for that component.</p><p>The <code>ComponentFixture</code> properties and methods provide access to the component, its DOM representation, and aspects of its Angular environment.</p><h3 id="componentfixture-properties" tabindex="-1"><code>ComponentFixture</code> properties <a class="header-anchor" href="#componentfixture-properties" aria-label="Permalink to &quot;\`ComponentFixture\` properties&quot;">​</a></h3><p>Here are the most important properties for testers, in order of likely utility.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Properties</th><th style="text-align:left;">Details</th></tr></thead><tbody><tr><td style="text-align:left;"><code>componentInstance</code></td><td style="text-align:left;">The instance of the component class created by <code>TestBed.createComponent</code>.</td></tr><tr><td style="text-align:left;"><code>debugElement</code></td><td style="text-align:left;">The <code>DebugElement</code> associated with the root element of the component. <br> The <code>debugElement</code> provides insight into the component and its DOM element during test and debugging. It&#39;s a critical property for testers. The most interesting members are covered <a href="#debugelement">below</a>.</td></tr><tr><td style="text-align:left;"><code>nativeElement</code></td><td style="text-align:left;">The native DOM element at the root of the component.</td></tr><tr><td style="text-align:left;"><code>changeDetectorRef</code></td><td style="text-align:left;">The <code>ChangeDetectorRef</code> of the component&#39;s host view, not of the component itself. See <a href="/en/guide/zoneless#using-zoneless-in-testbed">Using Zoneless in <code>TestBed</code></a>.</td></tr></tbody></table><h3 id="componentfixture-methods" tabindex="-1"><code>ComponentFixture</code> methods <a class="header-anchor" href="#componentfixture-methods" aria-label="Permalink to &quot;\`ComponentFixture\` methods&quot;">​</a></h3><p>The <em>fixture</em> methods cause Angular to perform certain tasks on the component tree. Call these methods to trigger Angular behavior in response to simulated user action.</p><p>Here are the most useful methods for testers.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Methods</th><th style="text-align:left;">Details</th></tr></thead><tbody><tr><td style="text-align:left;"><code>detectChanges</code></td><td style="text-align:left;">Trigger a change detection cycle for the component. <br> Call it to initialize the component (it calls <code>ngOnInit</code>) and after your test code, change the component&#39;s data bound property values. Angular can&#39;t see that you&#39;ve changed <code>personComponent.name</code> and won&#39;t update the <code>name</code> binding until you call <code>detectChanges</code>. <br> Runs <code>checkNoChanges</code> afterwards to confirm that there are no circular updates unless called as <code>detectChanges(false)</code>;</td></tr><tr><td style="text-align:left;"><code>autoDetectChanges</code></td><td style="text-align:left;">Set this to <code>true</code> when you want the fixture to detect changes automatically. <br> When autodetect is <code>true</code>, the test fixture calls <code>detectChanges</code> immediately after creating the component. Then it listens for pertinent zone events and calls <code>detectChanges</code> accordingly. When your test code modifies component property values directly, you probably still have to call <code>fixture.detectChanges</code> to trigger data binding updates. <br> The default is <code>true</code> with zoneless change detection (the <code>TestBed</code> default) and <code>false</code> with Zone-based change detection.</td></tr><tr><td style="text-align:left;"><code>checkNoChanges</code></td><td style="text-align:left;">Do a change detection run to make sure there are no pending changes. Throws an exceptions if there are.</td></tr><tr><td style="text-align:left;"><code>isStable</code></td><td style="text-align:left;">If the fixture is currently <em>stable</em>, returns <code>true</code>. If there are async tasks that have not completed, returns <code>false</code>.</td></tr><tr><td style="text-align:left;"><code>whenStable</code></td><td style="text-align:left;">Returns a promise that resolves when the fixture is stable. <br> To resume testing after completion of asynchronous activity or asynchronous change detection, hook that promise. See <a href="/en/guide/testing/components-scenarios#whenstable">whenStable</a>.</td></tr><tr><td style="text-align:left;"><code>destroy</code></td><td style="text-align:left;">Trigger component destruction.</td></tr></tbody></table><h4 id="debugelement" tabindex="-1"><code>DebugElement</code> <a class="header-anchor" href="#debugelement" aria-label="Permalink to &quot;\`DebugElement\`&quot;">​</a></h4><p>The <code>DebugElement</code> provides crucial insights into the component&#39;s DOM representation.</p><p>From the test root component&#39;s <code>DebugElement</code> returned by <code>fixture.debugElement</code>, you can walk (and query) the fixture&#39;s entire element and component subtrees.</p><p>Here are the most useful <code>DebugElement</code> members for testers, in approximate order of utility:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Members</th><th style="text-align:left;">Details</th></tr></thead><tbody><tr><td style="text-align:left;"><code>nativeElement</code></td><td style="text-align:left;">The corresponding DOM element in the browser</td></tr><tr><td style="text-align:left;"><code>query</code></td><td style="text-align:left;">Calling <code>query(predicate: Predicate&lt;DebugElement&gt;)</code> returns the first <code>DebugElement</code> that matches the predicate at any depth in the subtree.</td></tr><tr><td style="text-align:left;"><code>queryAll</code></td><td style="text-align:left;">Calling <code>queryAll(predicate: Predicate&lt;DebugElement&gt;)</code> returns all <code>DebugElements</code> that matches the predicate at any depth in subtree.</td></tr><tr><td style="text-align:left;"><code>injector</code></td><td style="text-align:left;">The host dependency injector. For example, the root element&#39;s component instance injector.</td></tr><tr><td style="text-align:left;"><code>componentInstance</code></td><td style="text-align:left;">The element&#39;s own component instance, if it has one.</td></tr><tr><td style="text-align:left;"><code>context</code></td><td style="text-align:left;">An object that provides parent context for this element. Often an ancestor component instance that governs this element. <br> When an element is repeated within <code>@for</code> block, the context is an <code>RepeaterContext</code> whose <code>$implicit</code> property is the value of the row instance value. For example, the <code>hero</code> in <code>@for(hero of heroes; ...)</code>.</td></tr><tr><td style="text-align:left;"><code>children</code></td><td style="text-align:left;">The immediate <code>DebugElement</code> children. Walk the tree by descending through <code>children</code>. <code>DebugElement</code> also has <code>childNodes</code>, a list of <code>DebugNode</code> objects. <code>DebugElement</code> derives from <code>DebugNode</code> objects and there are often more nodes than elements. Testers can usually ignore plain nodes.</td></tr><tr><td style="text-align:left;"><code>parent</code></td><td style="text-align:left;">The <code>DebugElement</code> parent. Null if this is the root element.</td></tr><tr><td style="text-align:left;"><code>name</code></td><td style="text-align:left;">The element tag name, if it is an element.</td></tr><tr><td style="text-align:left;"><code>triggerEventHandler</code></td><td style="text-align:left;">Triggers the event by its name if there is a corresponding listener in the element&#39;s <code>listeners</code> collection. The second parameter is the <em>event object</em> expected by the handler. <br> If the event lacks a listener or there&#39;s some other problem, consider calling <code>nativeElement.dispatchEvent(eventObject)</code>.</td></tr><tr><td style="text-align:left;"><code>listeners</code></td><td style="text-align:left;">The callbacks attached to the component&#39;s <code>@Output</code> properties and/or the element&#39;s event properties.</td></tr><tr><td style="text-align:left;"><code>providerTokens</code></td><td style="text-align:left;">This component&#39;s injector lookup tokens. Includes the component itself plus the tokens that the component lists in its <code>providers</code> metadata.</td></tr><tr><td style="text-align:left;"><code>references</code></td><td style="text-align:left;">Dictionary of objects associated with template local variables (for example, <code>#foo</code>), keyed by the local variable name.</td></tr></tbody></table><p>The <code>DebugElement.query(predicate)</code> and <code>DebugElement.queryAll(predicate)</code> methods take a predicate that filters the source element&#39;s subtree for matching <code>DebugElement</code>.</p><p>The predicate is any method that takes a <code>DebugElement</code> and returns a <em>truthy</em> value. The following example finds all <code>DebugElements</code> with a reference to a template local variable named &quot;content&quot;:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Filter for DebugElements with a #content reference</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> contentRefs</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> el.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">queryAll</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">((</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">de</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> de.references[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;content&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]);</span></span></code></pre></div><p>The Angular <code>By</code> class has three static methods for common predicates:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Static method</th><th style="text-align:left;">Details</th></tr></thead><tbody><tr><td style="text-align:left;"><code>By.all</code></td><td style="text-align:left;">Return all elements</td></tr><tr><td style="text-align:left;"><code>By.css(selector)</code></td><td style="text-align:left;">Return elements with matching CSS selectors</td></tr><tr><td style="text-align:left;"><code>By.directive(directive)</code></td><td style="text-align:left;">Return elements that Angular matched to an instance of the directive class</td></tr></tbody></table><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Can find DebugElement either by css selector or by directive</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> h2</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> fixture.debugElement.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">query</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(By.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">css</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;h2&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">));</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> directive</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> fixture.debugElement.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">query</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(By.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">directive</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Highlight));</span></span></code></pre></div>`,40)]))}const u=t(n,[["render",o]]);export{g as __pageData,u as default};
